import { NextRequest, NextResponse } from "next/server";

/**
 * API route for exchanging authorization code for access token
 * This handles the PKCE token exchange
 */
export async function POST(request: NextRequest) {
  try {
    const { code, codeVerifier } = await request.json();

    if (!code || !codeVerifier) {
      return NextResponse.json(
        { error: "Missing required parameters" },
        { status: 400 }
      );
    }

    // Exchange authorization code for access token
    const tokenResponse = await fetch(
      `${process.env.NEXT_PUBLIC_VALYU_AUTH_URL}/auth/v1/oauth/token`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: new URLSearchParams({
          grant_type: "authorization_code",
          code,
          redirect_uri: process.env.NEXT_PUBLIC_REDIRECT_URI!,
          client_id: process.env.NEXT_PUBLIC_VALYU_CLIENT_ID!,
          client_secret: process.env.VALYU_CLIENT_SECRET!,
          code_verifier: codeVerifier,
        }),
      }
    );

    if (!tokenResponse.ok) {
      const errorData = await tokenResponse.text();
      console.error("Token exchange failed:", errorData);
      return NextResponse.json(
        { error: "Token exchange failed", details: errorData },
        { status: tokenResponse.status }
      );
    }

    const tokenData = await tokenResponse.json();
    const { access_token, refresh_token, expires_in } = tokenData;

    // Get user info from Valyu platform
    const userInfoResponse = await fetch(
      `${process.env.VALYU_APP_URL}/api/oauth/userinfo`,
      {
        headers: {
          Authorization: `Bearer ${access_token}`,
        },
      }
    );

    if (!userInfoResponse.ok) {
      console.error("Failed to get user info");
      return NextResponse.json(
        { error: "Failed to get user info" },
        { status: userInfoResponse.status }
      );
    }

    const userInfo = await userInfoResponse.json();

    // Return tokens and user info to client
    return NextResponse.json({
      access_token,
      refresh_token,
      expires_in,
      user: {
        id: userInfo.sub,
        email: userInfo.email,
        name: userInfo.name,
        picture: userInfo.picture,
        email_verified: userInfo.email_verified,
      },
    });
  } catch (error) {
    console.error("Token exchange error:", error);
    return NextResponse.json(
      {
        error: "Internal server error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 }
    );
  }
}

/**
 * OAuth 2.0 with PKCE (Proof Key for Code Exchange) utilities
 */

/**
 * Generates a random code verifier for PKCE
 */
export function generateCodeVerifier(): string {
  const array = new Uint8Array(32);
  crypto.getRandomValues(array);
  return base64URLEncode(array);
}

/**
 * Generates a code challenge from a code verifier
 */
export async function generateCodeChallenge(verifier: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(verifier);
  const hash = await crypto.subtle.digest("SHA-256", data);
  return base64URLEncode(new Uint8Array(hash));
}

/**
 * Base64 URL encoding (without padding)
 */
function base64URLEncode(buffer: Uint8Array): string {
  const base64 = btoa(String.fromCharCode(...buffer));
  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}

/**
 * Check if OAuth is configured
 */
export function isOAuthConfigured(): boolean {
  return !!(
    process.env.NEXT_PUBLIC_VALYU_CLIENT_ID &&
    process.env.NEXT_PUBLIC_VALYU_AUTH_URL &&
    process.env.NEXT_PUBLIC_REDIRECT_URI
  );
}

/**
 * Initiates the OAuth flow by redirecting to the authorization endpoint
 */
export async function initiateOAuthFlow() {
  // Check if OAuth is configured
  if (!isOAuthConfigured()) {
    console.warn(
      "OAuth is not configured. Set NEXT_PUBLIC_VALYU_CLIENT_ID, NEXT_PUBLIC_VALYU_AUTH_URL, and NEXT_PUBLIC_REDIRECT_URI."
    );
    return;
  }

  // Generate PKCE parameters
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = await generateCodeChallenge(codeVerifier);

  // Store code verifier in sessionStorage (needed for token exchange)
  sessionStorage.setItem("oauth_code_verifier", codeVerifier);

  // Generate random state for CSRF protection
  const state = generateCodeVerifier();
  sessionStorage.setItem("oauth_state", state);

  // Build authorization URL
  const authUrl = new URL(
    "/auth/v1/oauth/authorize",
    process.env.NEXT_PUBLIC_VALYU_AUTH_URL
  );
  authUrl.searchParams.append(
    "client_id",
    process.env.NEXT_PUBLIC_VALYU_CLIENT_ID!
  );
  authUrl.searchParams.append(
    "redirect_uri",
    process.env.NEXT_PUBLIC_REDIRECT_URI!
  );
  authUrl.searchParams.append("response_type", "code");
  authUrl.searchParams.append("scope", "openid profile email");
  authUrl.searchParams.append("code_challenge", codeChallenge);
  authUrl.searchParams.append("code_challenge_method", "S256");
  authUrl.searchParams.append("state", state);

  // Redirect to authorization endpoint
  window.location.href = authUrl.toString();
}

/**
 * User info interface
 */
export interface UserInfo {
  sub: string;
  email: string;
  email_verified: boolean;
  name?: string;
  picture?: string;
  updated_at?: string;
}

import { create } from "zustand";

const TOKEN_STORAGE_KEY = "valyu_oauth_tokens";
const USER_STORAGE_KEY = "valyu_user";

export interface User {
  id: string;
  name: string;
  email: string;
  picture?: string;
  email_verified?: boolean;
}

interface TokenData {
  accessToken: string;
  refreshToken?: string;
  expiresAt: number;
}

interface AuthState {
  user: User | null;
  accessToken: string | null;
  refreshToken: string | null;
  tokenExpiresAt: number | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  initialized: boolean;
  signIn: (user: User, tokens: { accessToken: string; refreshToken?: string; expiresIn?: number }) => void;
  signOut: () => void;
  initialize: () => void;
  getAccessToken: () => string | null;
}

function saveTokens(tokens: TokenData): void {
  if (typeof window === "undefined") return;
  localStorage.setItem(TOKEN_STORAGE_KEY, JSON.stringify(tokens));
}

function loadTokens(): TokenData | null {
  if (typeof window === "undefined") return null;
  try {
    const stored = localStorage.getItem(TOKEN_STORAGE_KEY);
    if (!stored) return null;
    return JSON.parse(stored);
  } catch {
    return null;
  }
}

function clearTokens(): void {
  if (typeof window === "undefined") return;
  localStorage.removeItem(TOKEN_STORAGE_KEY);
}

function saveUser(user: User): void {
  if (typeof window === "undefined") return;
  localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(user));
}

function loadUser(): User | null {
  if (typeof window === "undefined") return null;
  try {
    const stored = localStorage.getItem(USER_STORAGE_KEY);
    if (!stored) return null;
    return JSON.parse(stored);
  } catch {
    return null;
  }
}

function clearUser(): void {
  if (typeof window === "undefined") return;
  localStorage.removeItem(USER_STORAGE_KEY);
}

export const useAuthStore = create<AuthState>()((set, get) => ({
  user: null,
  accessToken: null,
  refreshToken: null,
  tokenExpiresAt: null,
  isAuthenticated: false,
  isLoading: true,
  initialized: false,

  initialize: () => {
    if (get().initialized) return;
    set({ initialized: true });

    const user = loadUser();
    const tokens = loadTokens();

    if (user && tokens) {
      const now = Date.now();
      if (tokens.expiresAt > now) {
        set({
          user,
          accessToken: tokens.accessToken,
          refreshToken: tokens.refreshToken || null,
          tokenExpiresAt: tokens.expiresAt,
          isAuthenticated: true,
          isLoading: false,
        });
        return;
      } else {
        clearTokens();
        clearUser();
      }
    }

    set({
      user: null,
      accessToken: null,
      refreshToken: null,
      tokenExpiresAt: null,
      isAuthenticated: false,
      isLoading: false,
    });
  },

  signIn: (user, tokens) => {
    // Default to 7 days if no expiresIn provided
    const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
    const expiresAt = tokens.expiresIn
      ? Date.now() + tokens.expiresIn * 1000
      : Date.now() + SEVEN_DAYS_MS;

    saveUser(user);
    saveTokens({
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      expiresAt,
    });

    set({
      user,
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken || null,
      tokenExpiresAt: expiresAt,
      isAuthenticated: true,
      isLoading: false,
    });
  },

  signOut: () => {
    clearUser();
    clearTokens();

    set({
      user: null,
      accessToken: null,
      refreshToken: null,
      tokenExpiresAt: null,
      isAuthenticated: false,
      isLoading: false,
    });
  },

  getAccessToken: () => {
    const state = get();
    if (!state.accessToken) return null;

    if (state.tokenExpiresAt && Date.now() >= state.tokenExpiresAt - 30000) {
      return null;
    }

    return state.accessToken;
  },
}));

"use client";

import { useEffect } from "react";
import { useAuthStore } from "@/stores/auth-store";

export function AuthInitializer({ children }: { children: React.ReactNode }) {
  const initialize = useAuthStore((state) => state.initialize);

  useEffect(() => {
    initialize();
  }, [initialize]);

  return <>{children}</>;
}

"use client";

import { useState, useRef, useEffect } from "react";
import { Lock, LogOut, Loader2, Globe } from "lucide-react";
import { useAuthStore } from "@/stores/auth-store";
import { cn } from "@/lib/utils";
import { SignInModal } from "./sign-in-modal";

const APP_MODE = process.env.NEXT_PUBLIC_APP_MODE || "self-hosted";

export function SignInPanel() {
  const { user, isAuthenticated, isLoading, signOut } = useAuthStore();
  const [showDropdown, setShowDropdown] = useState(false);
  const [showSignInModal, setShowSignInModal] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setShowDropdown(false);
      }
    }

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleAuthButtonClick = () => {
    if (isAuthenticated) {
      setShowDropdown(!showDropdown);
    } else {
      setShowSignInModal(true);
    }
  };

  if (APP_MODE === "self-hosted") {
    return null;
  }

  return (
    <>
      <div
        className="fixed left-4 top-1/2 -translate-y-1/2 z-40"
        ref={dropdownRef}
      >
        <div className="flex flex-col gap-1 rounded-2xl border border-border bg-card p-2 shadow-lg">
          {/* User Avatar or Lock Icon */}
          <button
            onClick={handleAuthButtonClick}
            disabled={isLoading}
            className={cn(
              "flex h-14 w-14 items-center justify-center rounded-xl transition-colors",
              isAuthenticated ? "hover:bg-muted" : "bg-muted/50 hover:bg-muted",
              isLoading && "opacity-50 cursor-not-allowed"
            )}
          >
            {isLoading ? (
              <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
            ) : isAuthenticated && user ? (
              user.picture ? (
                <img
                  src={user.picture}
                  alt={user.name}
                  className="h-10 w-10 rounded-full object-cover"
                />
              ) : (
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-primary-foreground font-semibold">
                  {user.name?.charAt(0).toUpperCase() || "U"}
                </div>
              )
            ) : (
              <Lock className="h-5 w-5 text-muted-foreground" />
            )}
          </button>

          <div className="mx-2 border-t border-border" />

          <div className="flex h-14 w-14 items-center justify-center">
            <Globe className="h-6 w-6 text-red-500" />
          </div>
        </div>

        {/* User Dropdown */}
        {showDropdown && isAuthenticated && user && (
          <div className="absolute left-full top-0 ml-3 w-64 rounded-xl border border-border bg-card p-4 shadow-xl animate-in fade-in slide-in-from-left-2 duration-200">
            <div className="flex items-center gap-3">
              {user.picture ? (
                <img
                  src={user.picture}
                  alt={user.name}
                  className="h-10 w-10 rounded-full object-cover"
                />
              ) : (
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-primary-foreground font-semibold">
                  {user.name?.charAt(0).toUpperCase() || "U"}
                </div>
              )}
              <div className="flex-1 min-w-0">
                <p className="font-medium text-foreground truncate">
                  {user.name || "User"}
                </p>
                <p className="text-sm text-muted-foreground truncate">
                  {user.email}
                </p>
              </div>
            </div>

            <div className="mt-4 border-t border-border pt-4">
              <button
                onClick={() => {
                  signOut();
                  setShowDropdown(false);
                }}
                disabled={isLoading}
                className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-sm text-red-500 hover:bg-red-500/10 transition-colors disabled:opacity-50"
              >
                {isLoading ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <LogOut className="h-4 w-4" />
                )}
                Sign out
              </button>
            </div>
          </div>
        )}
      </div>

      <SignInModal open={showSignInModal} onOpenChange={setShowSignInModal} />
    </>
  );
}

export { SignInPanel } from "./sign-in-panel";
export { SignInModal } from "./sign-in-modal";
export { AuthInitializer } from "./auth-initializer";

"use client";

import { useState } from "react";
import { Loader2 } from "lucide-react";
import {
  Dialog,
  DialogHeader,
  DialogTitle,
  DialogContent,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { initiateOAuthFlow, isOAuthConfigured } from "@/lib/oauth";

interface SignInModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function ValyuLogoWithText() {
  return (
    <div className="flex items-center gap-2">
      <svg
        viewBox="0 0 24 24"
        fill="none"
        className="h-5 w-5"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M12 20L4 4h16L12 20z" />
      </svg>
      <span className="font-semibold tracking-wide">VALYU</span>
    </div>
  );
}

export function SignInModal({ open, onOpenChange }: SignInModalProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleValyuSignIn = async () => {
    setIsLoading(true);
    setError(null);

    // Check if OAuth is configured
    if (!isOAuthConfigured()) {
      setError(
        "OAuth is not configured. Please contact the administrator or use self-hosted mode."
      );
      setIsLoading(false);
      return;
    }

    try {
      // Initiate PKCE OAuth flow
      await initiateOAuthFlow();
    } catch (err) {
      console.error("OAuth initiation error:", err);
      setError("Failed to initiate sign in. Please try again.");
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading) {
      setError(null);
      onOpenChange(false);
    }
  };

  return (
    <Dialog open={open} onClose={handleClose} className="max-w-md">
      <DialogHeader onClose={handleClose}>
        <DialogTitle className="text-center text-xl">Sign in</DialogTitle>
      </DialogHeader>
      <DialogContent className="space-y-6">
        <p className="text-center text-sm text-muted-foreground">
          Sign in to access all features.
        </p>

        {/* Error Message */}
        {error && (
          <div className="rounded-lg bg-destructive/10 border border-destructive/20 p-3 text-sm text-destructive">
            {error}
          </div>
        )}

        {/* Sign In Button */}
        <Button
          onClick={handleValyuSignIn}
          disabled={isLoading}
          className="w-full h-12"
        >
          {isLoading ? (
            <>
              <Loader2 className="h-5 w-5 animate-spin mr-2" />
              Redirecting to Valyu...
            </>
          ) : (
            <>
              <span className="mr-2">Sign in with</span>
              <ValyuLogoWithText />
            </>
          )}
        </Button>

        <p className="text-center text-sm text-muted-foreground">
          Don&apos;t have an account? You can create one during sign-in.
        </p>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useCallback } from "react";
import type { EntityProfile } from "@/types";

export interface Deliverables {
  csv?: { url: string; title: string };
  pptx?: { url: string; title: string };
}

export interface EntitySearchResult {
  entity: EntityProfile;
  deliverables?: Deliverables;
  pdfUrl?: string;
}

interface SearchState {
  isLoading: boolean;
  error: string | null;
}

export function useValyuSearch() {
  const [state, setState] = useState<SearchState>({
    isLoading: false,
    error: null,
  });

  const searchEntity = useCallback(
    async (
      name: string,
      includeDeepResearch = false
    ): Promise<EntitySearchResult | null> => {
      setState({ isLoading: true, error: null });

      try {
        const response = await fetch("/api/entities", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ name, includeDeepResearch }),
        });

        if (!response.ok) {
          throw new Error("Entity search failed");
        }

        const data = await response.json();
        setState({ isLoading: false, error: null });
        return {
          entity: data.entity,
          deliverables: data.deliverables,
          pdfUrl: data.pdfUrl,
        };
      } catch (err) {
        const error =
          err instanceof Error ? err.message : "Unknown error occurred";
        setState({ isLoading: false, error });
        return null;
      }
    },
    []
  );

  const generateReport = useCallback(
    async (
      topic: string,
      type?: string
    ): Promise<{ summary: string; sources: { title: string; url: string }[] } | null> => {
      setState({ isLoading: true, error: null });

      try {
        const response = await fetch("/api/reports", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ topic, type }),
        });

        if (!response.ok) {
          throw new Error("Report generation failed");
        }

        const data = await response.json();
        setState({ isLoading: false, error: null });
        return {
          summary: data.report.summary,
          sources: data.report.sources,
        };
      } catch (err) {
        const error =
          err instanceof Error ? err.message : "Unknown error occurred";
        setState({ isLoading: false, error });
        return null;
      }
    },
    []
  );

  return {
    ...state,
    searchEntity,
    generateReport,
  };
}

"use client";

import { useEffect, useState, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useAuthStore } from "@/stores/auth-store";

export const dynamic = "force-dynamic";

function OAuthCallbackContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const signIn = useAuthStore((state) => state.signIn);
  const [status, setStatus] = useState<"processing" | "success" | "error">("processing");
  const [errorMessage, setErrorMessage] = useState("");

  useEffect(() => {
    const handleCallback = async () => {
      const code = searchParams.get("code");
      const state = searchParams.get("state");
      const error = searchParams.get("error");

      if (error) {
        setStatus("error");
        setErrorMessage("Authorization failed. Please try again.");
        setTimeout(() => router.push("/"), 3000);
        return;
      }

      if (!code || !state) {
        setStatus("error");
        setErrorMessage("Invalid callback parameters.");
        setTimeout(() => router.push("/"), 3000);
        return;
      }

      const storedState = sessionStorage.getItem("oauth_state");
      if (state !== storedState) {
        setStatus("error");
        setErrorMessage("Invalid state parameter. Possible CSRF attack.");
        setTimeout(() => router.push("/"), 3000);
        return;
      }

      const codeVerifier = sessionStorage.getItem("oauth_code_verifier");
      if (!codeVerifier) {
        setStatus("error");
        setErrorMessage("Code verifier not found. Please try again.");
        setTimeout(() => router.push("/"), 3000);
        return;
      }

      try {
        const tokenResponse = await fetch("/api/oauth/token", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ code, codeVerifier }),
        });

        if (!tokenResponse.ok) {
          const errorData = await tokenResponse.json();
          throw new Error(errorData.error || "Token exchange failed");
        }

        const { access_token, refresh_token, expires_in, user } = await tokenResponse.json();

        sessionStorage.removeItem("oauth_code_verifier");
        sessionStorage.removeItem("oauth_state");

        signIn(
          {
            id: user.sub || user.id,
            name: user.name || user.email,
            email: user.email,
            picture: user.picture,
            email_verified: user.email_verified,
          },
          {
            accessToken: access_token,
            refreshToken: refresh_token,
            expiresIn: expires_in || 3600,
          }
        );

        setStatus("success");
        setTimeout(() => router.push("/"), 1000);
      } catch (error) {
        console.error("OAuth callback error:", error);
        setStatus("error");
        setErrorMessage(error instanceof Error ? error.message : "Authentication failed");
        setTimeout(() => router.push("/"), 3000);
      }
    };

    handleCallback();
  }, [searchParams, router, signIn]);

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-card border border-border rounded-lg shadow-lg p-8 text-center">
        {status === "processing" && (
          <>
            <div className="w-16 h-16 mx-auto mb-6">
              <div className="w-16 h-16 border-4 border-border border-t-primary rounded-full animate-spin"></div>
            </div>
            <h2 className="text-xl font-semibold text-foreground mb-2">
              Signing you in...
            </h2>
            <p className="text-sm text-muted-foreground">
              Please wait while we complete your authentication.
            </p>
          </>
        )}

        {status === "success" && (
          <>
            <div className="w-16 h-16 mx-auto mb-6 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center">
              <svg
                className="w-8 h-8 text-green-600 dark:text-green-400"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M5 13l4 4L19 7"
                />
              </svg>
            </div>
            <h2 className="text-xl font-semibold text-foreground mb-2">
              Success!
            </h2>
            <p className="text-sm text-muted-foreground">
              Redirecting you to the app...
            </p>
          </>
        )}

        {status === "error" && (
          <>
            <div className="w-16 h-16 mx-auto mb-6 bg-red-100 dark:bg-red-900/30 rounded-full flex items-center justify-center">
              <svg
                className="w-8 h-8 text-red-600 dark:text-red-400"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </div>
            <h2 className="text-xl font-semibold text-foreground mb-2">
              Authentication Failed
            </h2>
            <p className="text-sm text-muted-foreground">{errorMessage}</p>
          </>
        )}
      </div>
    </div>
  );
}

